B=Block('b')
def pg(n):return [151 if n<=573 else 152 if n<=580 else 156 if n<=586 else 157 if n<=599 else 158]
def put(n,part,condition,answer,steps,p,v,views=None,**kw):
 B.add(n,part,condition,answer,steps,p,v,views,printed=pg(n),**kw)
def right(a,b):return dict(A=[a,0],B=[0,b],C=[0,0])
def rview(extra=(),segs=(),**kw):return sc(list('ABC')+list(extra),tri()+list(segs),rightAngles=[rt('A','C','B')],**kw)
def isosc(base,h):return dict(A=[-base/2,0],B=[0,h],C=[base/2,0],H=[0,0])
def iview(height=False):return sc('ABCH' if height else 'ABC',tri()+([['B','H']] if height else []),**({'rightAngles':[rt('A','H','B')]} if height else {}))
def sss(a,b,c):
 x=(b*b+c*c-a*a)/(2*c);return dict(A=[0,0],B=[c,0],C=[x,math.sqrt(b*b-x*x)])
def incircle(p):
 a=dist(p['B'],p['C']);b=dist(p['A'],p['C']);c=dist(p['A'],p['B']);p=dict(p)
 p['O']=[(a*p['A'][i]+b*p['B'][i]+c*p['C'][i])/(a+b+c) for i in (0,1)]
 for name,u,v in [('P','A','B'),('Q','B','C'),('R','C','A')]:p[name]=foot(p['O'],p[u],p[v])
 return p
def inview(p,center=False):
 return sc(list('ABCPQR')+(['O'] if center else []),tri()+([['O','P'],['O','Q'],['O','R']] if center else []),circles=[circle('O','P')],**({'rightAngles':[rt('O','P','A'),rt('O','Q','B'),rt('O','R','C')]} if center else {}))
def rhomb(d1,d2):return dict(A=[-d1/2,0],B=[0,d2/2],C=[d1/2,0],D=[0,-d2/2],O=[0,0])
def rhview(o=False,marks=False):return sc('ABCDO' if o else 'ABCD',poly()+[['A','C'],['B','D']],**({'rightAngles':[rt('A','O','B')]} if marks else {}))
def trapez(a,c,h,left=0):return dict(A=[left,h],B=[left+a,h],C=[c,0],D=[0,0])
def height_trap(p,vertex='A'):
 p=dict(p);p['H']=[p[vertex][0],0];return p
def tv(p,height=False,vertex='A'):
 return sc('ABCDH' if height else 'ABCD',poly()+([[vertex,'H']] if height else []),**({'rightAngles':[rt(vertex,'H','C')]} if height else {}))

